{
  "name": "Triage support messages",
  "description": "Summarises each support message and alerts on the urgent ones.",
  "nodes": [
    {
      "id": "trigger",
      "type": "core.webhook_trigger",
      "config": {}
    },
    {
      "id": "summarise",
      "type": "ai.llm",
      "label": "Summarise",
      "config": {
        "prompt": "Summarise this support message in one sentence: {{trigger.message}}"
      }
    },
    {
      "id": "decide",
      "type": "ai.agent",
      "label": "Decide urgency",
      "config": {
        "objective": "Decide whether this support message is urgent: {{steps.summarise.output.text}}",
        "choices": [
          "urgent",
          "normal"
        ]
      }
    },
    {
      "id": "route",
      "type": "core.branch",
      "config": {
        "left": "{{input.decision}}",
        "operator": "equals",
        "right": "urgent"
      }
    },
    {
      "id": "post_discord",
      "type": "integration.discord",
      "label": "Alert on Discord",
      "config": {
        "content": "Urgent: {{steps.summarise.output.text}}"
      }
    },
    {
      "id": "post_slack",
      "type": "integration.slack",
      "label": "Alert on Slack",
      "config": {
        "text": "Urgent: {{steps.summarise.output.text}}"
      }
    },
    {
      "id": "log_normal",
      "type": "core.log",
      "label": "Log the rest",
      "config": {
        "message": "Normal: {{steps.summarise.output.text}}"
      }
    }
  ],
  "edges": [
    {
      "source": "trigger",
      "target": "summarise",
      "sourceHandle": null
    },
    {
      "source": "summarise",
      "target": "decide",
      "sourceHandle": null
    },
    {
      "source": "decide",
      "target": "route",
      "sourceHandle": null
    },
    {
      "source": "route",
      "target": "post_discord",
      "sourceHandle": "true"
    },
    {
      "source": "route",
      "target": "post_slack",
      "sourceHandle": "true"
    },
    {
      "source": "route",
      "target": "log_normal",
      "sourceHandle": "false"
    }
  ],
