{
  "name": "Morning digest",
  "description": "Posts a summary of the top stories every weekday morning.",
  "nodes": [
    {
      "id": "every_weekday",
      "type": "core.schedule_trigger",
      "config": {
        "cron": "0 7 * * 1-5"
      }
    },
    {
      "id": "fetch",
      "type": "integration.http",
      "label": "Fetch top stories",
      "config": {
        "method": "GET",
        "url": "https://hacker-news.firebaseio.com/v0/topstories.json"
      }
    },
    {
      "id": "summarise",
      "type": "ai.llm",
      "config": {
        "prompt": "Summarise these top story ids for a team channel: {{steps.fetch.output.text}}"
      }
    },
    {
      "id": "post",
      "type": "integration.slack",
      "label": "Post the digest",
      "config": {
        "text": "{{steps.summarise.output.text}}"
      }
    }
  ],
  "edges": [
    {
      "source": "every_weekday",
      "target": "fetch",
      "sourceHandle": null
    },
    {
      "source": "fetch",
      "target": "summarise",
      "sourceHandle": null
    },
    {
      "source": "summarise",
      "target": "post",
      "sourceHandle": null
    }
  ],
  "unsupported": []
}

